CREATE TABLE IF NOT EXISTS fantasy_match_stats (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_day INT NOT NULL, player_name TEXT NOT NULL, goals INT NOT NULL DEFAULT 0, assists INT NOT NULL DEFAULT 0, clean_sheet BOOLEAN NOT NULL DEFAULT false, saves INT NOT NULL DEFAULT 0, yellow_cards INT NOT NULL DEFAULT 0, red_cards INT NOT NULL DEFAULT 0, own_goals INT NOT NULL DEFAULT 0, fantasy_points INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now())